CREATE OR REPLACE FUNCTION private.analytics_in_polygon(p_lng double precision, p_lat double precision, p_rings jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
 if not private.analytics_in_ring(p_lng,p_lat,p_rings->0) then return false; end if;
 for i in 1..jsonb_array_length(p_rings)-1 loop
   if private.analytics_in_ring(p_lng,p_lat,p_rings->i) then return false; end if;
 end loop;
 return true;
end;$function$

CREATE OR REPLACE FUNCTION private.analytics_in_ring(p_lng double precision, p_lat double precision, p_ring jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare inside boolean:=false; n integer:=jsonb_array_length(p_ring); j integer:=n-1;
 xi double precision;yi double precision;xj double precision;yj double precision;
begin
 for i in 0..n-1 loop
   xi:=(p_ring->i->>0)::double precision; yi:=(p_ring->i->>1)::double precision;
   xj:=(p_ring->j->>0)::double precision; yj:=(p_ring->j->>1)::double precision;
   if (yi>p_lat)<>(yj>p_lat) then
     if p_lng<((xj-xi)*(p_lat-yi))/(yj-yi)+xi then inside:=not inside; end if;
   end if;
   j:=i;
 end loop;
 return inside;
end;$function$

CREATE OR REPLACE FUNCTION private.analytics_law(p_raw text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare t text:=btrim(p_raw);m text[];
begin
 if t is null or t='' then return null;end if;
 m:=regexp_match(t,'^([가-힣·\s]{1,60}?법)\s*제\s*0*([0-9]+)\s*조(?:\s*의\s*0*([0-9]+))?(?:\s*제?\s*[0-9]{1,3}\s*항)?$');
 if m is null then return t;end if;
 return regexp_replace(m[1],'\s+','','g')||' 제'||m[2]||'조'||case when m[3] is null then '' else '의'||m[3] end;
end;$function$

CREATE OR REPLACE FUNCTION private.analytics_region(p_key text, p_lat double precision, p_lng double precision)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare tokens text[];sido text;v_code text;codes text[];g jsonb;poly jsonb;
begin
 if p_key is null then return null; end if;
 tokens:=regexp_split_to_array(btrim(p_key),'\s+');
 if cardinality(tokens)<2 then return null;end if;
 select t.code into sido from private.analytics_region_tokens t where t.token=tokens[1];
 if sido is null then return null;end if;
 if sido='36' then return '36110';end if;
 select s.codes into codes from private.analytics_region_splits s where s.key=sido||'|'||tokens[2];
 if codes is not null then
   if p_lat is null or p_lng is null then return null;end if;
   foreach v_code in array codes loop
     select geometry into g from private.analytics_region_geometry where analytics_region_geometry.code=v_code;
     if g->>'type'='Polygon' then
       if private.analytics_in_polygon(p_lng,p_lat,g->'coordinates') then return v_code;end if;
     else
       for poly in select value from jsonb_array_elements(g->'coordinates') loop
         if private.analytics_in_polygon(p_lng,p_lat,poly) then return v_code;end if;
       end loop;
     end if;
   end loop;
   return null;
 end if;
 select t.code into v_code from private.analytics_region_names t where t.key=sido||'|'||tokens[2];
 return v_code;
end;$function$

CREATE OR REPLACE FUNCTION private.community_current_policy(p_lock boolean)
 RETURNS private.community_policies
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v private.community_policies%rowtype;
begin
    if p_lock then
        perform 1 from private.community_policy_current where singleton for share;
    end if;
    select p.* into v from private.community_policies p
      join private.community_policy_current c on c.version = p.version where c.singleton;
    return v;
end;
$function$

CREATE OR REPLACE FUNCTION private.community_facts_manifest_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_old_in boolean := tg_op in ('UPDATE', 'DELETE') and old.public_state = 'completed';
    v_new_in boolean := tg_op in ('UPDATE', 'INSERT') and new.public_state = 'completed';
begin
    -- Only a change of the COMPLETED key set counts (N-11): a completed key appears, disappears or moves.
    if v_old_in and (not v_new_in or old.contributor_id <> new.contributor_id or old.dataset_key <> new.dataset_key
                     or old.source_report_key <> new.source_report_key) then
        perform private.community_bump_manifest(old.contributor_id, old.dataset_key);
    end if;
    if v_new_in and (not v_old_in or old.contributor_id <> new.contributor_id or old.dataset_key <> new.dataset_key
                     or old.source_report_key <> new.source_report_key) then
        perform private.community_bump_manifest(new.contributor_id, new.dataset_key);
    end if;
    return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.community_lock_contributor(p_user uuid, p_create boolean)
 RETURNS private.contributor_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v private.contributor_profiles%rowtype;
begin
    if p_create then
        insert into private.contributor_profiles(user_id, consent_version, privacy_policy_version, consented_at, revoked_at, status)
        values (p_user, 'none', 'none', now(), now(), 'active')
        on conflict (user_id) do nothing;
    end if;
    select * into v from private.contributor_profiles where user_id = p_user for update;
    return v;
end;
$function$

CREATE OR REPLACE FUNCTION private.community_stamp_registry_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    NEW.agency_registry_version := (select version from private.community_registry_state);
    return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION private.my_reports_check_query(p_kind text, p_query text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v text;
begin
    if p_kind = 'vehicle' then
        v := private.my_reports_norm_vehicle(p_query);
        if v is null or char_length(v) not between 6 and 64 then raise exception 'INVALID_QUERY'; end if;
    elsif p_kind = 'address' then
        v := private.my_reports_norm_address(p_query);
        if v is null or char_length(v) not between 5 and 200 then raise exception 'INVALID_QUERY'; end if;
    else
        raise exception 'INVALID_QUERY';
    end if;
    if v ~ '[\u0001-\u001f\u007f-\u009f]' then raise exception 'INVALID_QUERY'; end if;
    return v;
end;
$function$

CREATE OR REPLACE FUNCTION private.my_reports_gate(p_user uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_id jsonb;
    v_profile private.contributor_profiles%rowtype;
    v_contributor text;
begin
    v_id := private.community_identity_state(p_user, p_session);
    select * into v_profile from private.contributor_profiles where user_id = p_user;
    v_contributor := case
        when v_profile.user_id is null then 'none'
        when v_profile.status <> 'active' then 'suspended'
        when exists (select 1 from private.community_consent_grants g where g.user_id = p_user and g.revoked_at is null) then 'active'
        when exists (select 1 from private.community_consent_grants g where g.user_id = p_user) then 'revoked'
        else 'none' end;
    return jsonb_build_object(
        'error', case
            when not coalesce((v_id->>'user_ok')::boolean, false) then 'ACCOUNT_INELIGIBLE'
            when not coalesce((v_id->>'kakao')::boolean, false) then 'KAKAO_REQUIRED'
            when not coalesce((v_id->>'session')::boolean, false) then 'SESSION_EXPIRED'
            when v_contributor = 'suspended' then 'ACCOUNT_INELIGIBLE'
            else null end,
        'contributor', v_contributor);
end;
$function$

CREATE OR REPLACE FUNCTION private.safeauth_expire_if_needed(p_row private.community_auth_requests)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if p_row.status in ('device_confirmed', 'cancelled', 'expired', 'failed') then
        return p_row.status;
    end if;
    if p_row.expires_at <= now() then
        update private.community_auth_requests
           set status = 'expired', encrypted_auth_code = null
         where id = p_row.id;
        return 'expired';
    end if;
    return p_row.status;
end;
$function$

CREATE OR REPLACE FUNCTION private.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    new.updated_at = now();
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_account_grant_consent(p_user uuid, p_session uuid, p_policy_version text, p_text_sha256 text, p_via text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_policy private.community_policies%rowtype := private.community_current_policy(true);
    v_id jsonb := private.community_identity_state(p_user, p_session);
    v_profile private.contributor_profiles%rowtype;
    v_grant private.community_consent_grants%rowtype;
    v_new_id uuid;
    v_lineage uuid;
begin
    if not ((v_id->>'user_ok')::boolean and (v_id->>'kakao')::boolean and (v_id->>'session')::boolean) then
        return jsonb_build_object('error', 'kakao_required');
    end if;
    if p_policy_version is distinct from v_policy.version or p_text_sha256 is distinct from v_policy.consent_text_sha256 then
        return jsonb_build_object('error', 'policy_mismatch', 'required_version', v_policy.version);
    end if;
    if p_via is null or p_via not in ('safetyreport_server', 'mobile_standalone', 'mobile_client') then
        return jsonb_build_object('error', 'invalid_request');
    end if;
    v_profile := private.community_lock_contributor(p_user, true);
    if v_profile.status <> 'active' then return jsonb_build_object('error', 'contributor_suspended'); end if;
    select * into v_grant from private.community_consent_grants where user_id = p_user and revoked_at is null for update;
    if private.community_grant_is_current(v_grant, v_policy) then
        return jsonb_build_object('grant_id', v_grant.grant_id, 'policy_version', v_grant.policy_version,
            'granted_at', v_grant.granted_at, 'created', false);
    end if;
    v_new_id := gen_random_uuid();
    if v_grant.grant_id is not null then
        -- outdated-policy grant: close it and continue its lineage (not a user revocation)
        update private.community_consent_grants set revoked_at = now(), revoked_session_id = p_session,
            revoke_reason = 'superseded_policy', superseded_by = v_new_id where grant_id = v_grant.grant_id;
        v_lineage := v_grant.lineage_id;
    else
        v_lineage := v_new_id;
    end if;
    insert into private.community_consent_grants(grant_id, lineage_id, user_id, policy_version, consent_text_sha256,
        granted_via, granted_session_id)
    values (v_new_id, v_lineage, p_user, v_policy.version, v_policy.consent_text_sha256, p_via, p_session)
    returning * into v_grant;
    update private.contributor_profiles set consent_version = v_policy.version,
        privacy_policy_version = v_policy.version, consented_at = v_grant.granted_at,
        revoked_at = null, updated_at = now() where user_id = p_user;
    return jsonb_build_object('grant_id', v_grant.grant_id, 'policy_version', v_grant.policy_version,
        'granted_at', v_grant.granted_at, 'created', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_account_policy()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_policy private.community_policies%rowtype := private.community_current_policy(false);
    v_text text;
begin
    select t.consent_text into v_text from private.community_policy_texts t
     where t.consent_text_sha256 = v_policy.consent_text_sha256;
    if v_text is null then
        return jsonb_build_object('error', 'server_error');
    end if;
    return jsonb_build_object('policy', jsonb_build_object(
        'version', v_policy.version,
        'consent_text_sha256', v_policy.consent_text_sha256,
        'consent_text', v_text));
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_account_rebind_connection(p_user uuid, p_session uuid, p_connection uuid, p_secret_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_policy private.community_policies%rowtype := private.community_current_policy(true);
    v_id jsonb := private.community_identity_state(p_user, p_session);
    v_conn private.community_connections%rowtype;
begin
    if not ((v_id->>'user_ok')::boolean and (v_id->>'kakao')::boolean and (v_id->>'session')::boolean) then
        return jsonb_build_object('error', 'kakao_required');
    end if;
    perform private.community_lock_contributor(p_user, false);
    select * into v_conn from private.community_connections where connection_id = p_connection for update;
    -- Same answer for "no such connection", "someone else's connection" and "wrong secret" (no oracle).
    if v_conn.connection_id is null or v_conn.user_id <> p_user or v_conn.connection_secret_sha256 <> p_secret_sha256 then
        return jsonb_build_object('error', 'not_found');
    end if;
    if v_conn.status <> 'active' then return jsonb_build_object('error', 'connection_' || v_conn.status); end if;
    update private.community_connections set bound_session_id = p_session, rebound_at = now()
     where connection_id = p_connection;
    return jsonb_build_object('connection_id', p_connection, 'writer_epoch', v_conn.writer_epoch,
        'last_accepted_revision', v_conn.last_accepted_revision);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_account_register_connection(p_user uuid, p_session uuid, p_source_app text, p_source_mode text, p_platform text, p_device_label text, p_dataset_key text, p_secret_sha256 text, p_takeover boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_policy private.community_policies%rowtype := private.community_current_policy(true);
    v_id jsonb := private.community_identity_state(p_user, p_session);
    v_other private.community_connections%rowtype;
    v_new private.community_connections%rowtype;
begin
    if not ((v_id->>'user_ok')::boolean and (v_id->>'kakao')::boolean and (v_id->>'session')::boolean) then
        return jsonb_build_object('error', 'kakao_required');
    end if;
    perform private.community_lock_contributor(p_user, true);
    select * into v_other from private.community_connections
     where user_id = p_user and dataset_key = p_dataset_key and status = 'active' for update;
    if v_other.connection_id is not null then
        if not coalesce(p_takeover, false) then
            return jsonb_build_object('error', 'writer_conflict', 'active_writer', jsonb_build_object(
                'device_label', v_other.device_label, 'platform', v_other.platform, 'source_app', v_other.source_app,
                'created_at', v_other.created_at));
        end if;
        update private.community_connections set status = 'superseded', revoked_at = now(), revoke_reason = 'takeover'
         where connection_id = v_other.connection_id;
    end if;
    insert into private.community_connections(user_id, bound_session_id, connection_secret_sha256, source_app,
        source_mode, platform, device_label, dataset_key)
    values (p_user, p_session, p_secret_sha256, p_source_app, p_source_mode, p_platform, p_device_label, p_dataset_key)
    returning * into v_new;
    return jsonb_build_object('connection_id', v_new.connection_id, 'writer_epoch', v_new.writer_epoch,
        'superseded_previous', v_other.connection_id is not null);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_account_revoke_connection(p_user uuid, p_connection uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_policy private.community_policies%rowtype := private.community_current_policy(true);
    v_conn private.community_connections%rowtype;
begin
    perform private.community_lock_contributor(p_user, false);
    select * into v_conn from private.community_connections where connection_id = p_connection for update;
    if v_conn.connection_id is null or v_conn.user_id <> p_user then return jsonb_build_object('error', 'not_found'); end if;
    if v_conn.status = 'active' then
        update private.community_connections set status = 'revoked', revoked_at = now(), revoke_reason = 'user'
         where connection_id = p_connection;
    end if;
    return jsonb_build_object('connection_id', p_connection, 'status', 'revoked');
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_account_revoke_consent(p_user uuid, p_session uuid, p_grant uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_policy private.community_policies%rowtype := private.community_current_policy(true);
    v_given private.community_consent_grants%rowtype;
    v_active private.community_consent_grants%rowtype;
begin
    perform private.community_lock_contributor(p_user, false);
    select * into v_given from private.community_consent_grants where grant_id = p_grant and user_id = p_user;
    if v_given.grant_id is null then return jsonb_build_object('error', 'not_found'); end if;
    select * into v_active from private.community_consent_grants
     where user_id = p_user and lineage_id = v_given.lineage_id and revoked_at is null for update;
    if v_active.grant_id is null then
        -- The given lineage is already closed. If the user now has ANOTHER active lineage, this request refers to an
        -- outdated consent: refuse instead of reporting a success the user would misread (N-04-L).
        if exists (select 1 from private.community_consent_grants where user_id = p_user and revoked_at is null) then
            return jsonb_build_object('error', 'stale_grant');
        end if;
        return jsonb_build_object('grant_id', p_grant, 'revoked', true, 'already_revoked', true, 'lineage_active', false);
    end if;
    update private.community_consent_grants set revoked_at = now(), revoked_session_id = p_session, revoke_reason = 'user'
     where grant_id = v_active.grant_id;
    update private.contributor_profiles set revoked_at = now(), updated_at = now() where user_id = p_user;
    return jsonb_build_object('grant_id', v_active.grant_id, 'revoked', true, 'already_revoked', false,
        'lineage_active', private.community_lineage_active(v_active.grant_id));
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_account_status(p_user uuid, p_session uuid, p_connection uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_id jsonb := private.community_identity_state(p_user, p_session);
    v_policy private.community_policies%rowtype := private.community_current_policy(false);
    v_grant private.community_consent_grants%rowtype;
    v_last_revoked timestamptz;
    v_profile private.contributor_profiles%rowtype;
    v_conn private.community_connections%rowtype;
    v_reasons text[] := '{}';
    v_consent_state text;
    v_kakao boolean;
    v_ready boolean;
begin
    select * into v_profile from private.contributor_profiles where user_id = p_user;
    select * into v_grant from private.community_consent_grants where user_id = p_user and revoked_at is null;
    select max(revoked_at) into v_last_revoked from private.community_consent_grants where user_id = p_user;
    v_kakao := (v_id->>'user_ok')::boolean and (v_id->>'kakao')::boolean and (v_id->>'session')::boolean;
    if not (v_id->>'user_ok')::boolean then v_reasons := array_append(v_reasons, 'user_not_eligible'); end if;
    if not (v_id->>'kakao')::boolean then v_reasons := array_append(v_reasons, 'kakao_missing'); end if;
    if not (v_id->>'session')::boolean then v_reasons := array_append(v_reasons, 'session_missing'); end if;
    if v_grant.grant_id is null then
        v_consent_state := case when v_last_revoked is null then 'none' else 'revoked' end;
        v_reasons := array_append(v_reasons, 'consent_' || v_consent_state);
    elsif not private.community_grant_is_current(v_grant, v_policy) then
        v_consent_state := 'outdated';
        v_reasons := array_append(v_reasons, 'consent_outdated');
    else
        v_consent_state := 'active';
    end if;
    if v_profile.user_id is not null and v_profile.status <> 'active' then
        v_reasons := array_append(v_reasons, 'contributor_suspended');
    end if;
    if p_connection is not null then
        select * into v_conn from private.community_connections where connection_id = p_connection and user_id = p_user;
    end if;
    select ready into v_ready from private.analytics_state where singleton;
    return jsonb_build_object(
        'gate', jsonb_build_object('kakao', v_kakao, 'consent', v_consent_state = 'active',
            'can_enter', v_kakao and v_consent_state = 'active' and coalesce(v_profile.status, 'active') = 'active',
            'reasons', to_jsonb(v_reasons)),
        'policy', jsonb_build_object('required_version', v_policy.version, 'consent_text_sha256', v_policy.consent_text_sha256),
        'consent', jsonb_build_object('state', v_consent_state, 'grant_id', v_grant.grant_id,
            'policy_version', v_grant.policy_version, 'consent_text_sha256', v_grant.consent_text_sha256,
            'granted_at', v_grant.granted_at),
        'contributor', jsonb_build_object('status', case when v_profile.user_id is null then 'none' else v_profile.status end),
        'connection', case when v_conn.connection_id is null then null else jsonb_build_object(
            'status', v_conn.status, 'writer_epoch', v_conn.writer_epoch,
            'bound_to_current_session', v_conn.bound_session_id = p_session,
            'last_accepted_revision', v_conn.last_accepted_revision,
            'source_app', v_conn.source_app, 'source_mode', v_conn.source_mode, 'dataset_key', v_conn.dataset_key) end,
        'projection', jsonb_build_object('ready', coalesce(v_ready, false)));
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_activate_snapshot(p_snapshot_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_expected integer;
    v_received integer;
    v_payload_sha256 text;
    v_computed_sha256 text;
begin
    -- Serializes activation for one contributor.
    perform 1
      from private.contributor_profiles
     where user_id = p_user_id
       and status = 'active'
       and revoked_at is null
     for update;

    if not found then
        raise exception 'active contributor profile not found';
    end if;

    select expected_point_count, received_point_count, payload_sha256
      into v_expected, v_received, v_payload_sha256
      from private.upload_snapshots
     where id = p_snapshot_id
       and user_id = p_user_id
       and state = 'staged'
     for update;

    if not found then
        raise exception 'staged snapshot not found';
    end if;

    if v_expected <> v_received then
        raise exception 'snapshot point count mismatch';
    end if;

    -- payload_sha256 = sha256 of all chunk hashes concatenated in chunk order
    -- (docs/data-contract.md section 7).
    select encode(extensions.digest(
               coalesce(string_agg(chunk_sha256, '' order by chunk_index), ''),
               'sha256'), 'hex')
      into v_computed_sha256
      from private.upload_chunks
     where snapshot_id = p_snapshot_id;

    if v_computed_sha256 is distinct from v_payload_sha256 then
        raise exception 'snapshot payload hash mismatch';
    end if;

    update private.upload_snapshots
       set state = 'superseded',
           superseded_at = now(),
           superseded_by = p_snapshot_id
     where user_id = p_user_id
       and state = 'active';

    update private.upload_snapshots
       set state = 'active',
           finalized_at = now()
     where id = p_snapshot_id;

    update private.contributor_profiles
       set last_upload_at = now()
     where user_id = p_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_agency_recompute_apply(p_version text, p_updates jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_state text;
  v_row record;
  v_count integer;
  v_applied integer := 0;
  v_skipped integer := 0;
begin
  -- Lock the singleton through this transaction. A concurrent version change
  -- cannot commit between the version check and the fact updates.
  select s.version into v_state from private.community_registry_state s
   where s.id = 1 for share;
  if p_version is null or p_version is distinct from v_state then
    raise exception 'REGISTRY_VERSION_MISMATCH';
  end if;
  if p_updates is null or jsonb_typeof(p_updates) <> 'array' or
     jsonb_array_length(p_updates) > 5000 then
    raise exception 'INVALID_RECOMPUTE_BATCH';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(p_updates) as x(
      contributor_id uuid, dataset_key text, source_report_key text)
    group by x.contributor_id, x.dataset_key, x.source_report_key having count(*) > 1
  ) then
    raise exception 'DUPLICATE_RECOMPUTE_ROW';
  end if;

  for v_row in select * from jsonb_to_recordset(p_updates) as x(
    contributor_id uuid, dataset_key text, source_report_key text,
    source_agency_code text, agency_name text, manager_name text,
    expected_agency_key text, expected_agency_current_name text,
    expected_manager_key text, expected_agency_registry_version text,
    agency_key text, agency_current_name text, manager_key text)
  loop
    if v_row.contributor_id is null or v_row.dataset_key is null or
       v_row.source_report_key is null then
      raise exception 'INVALID_RECOMPUTE_ROW';
    end if;
    update private.community_report_facts f
       set agency_key = v_row.agency_key,
           agency_current_name = v_row.agency_current_name,
           manager_key = v_row.manager_key,
           agency_registry_version = p_version
     where f.contributor_id = v_row.contributor_id
       and f.dataset_key = v_row.dataset_key
       and f.source_report_key = v_row.source_report_key
       and f.agency_registry_version is not distinct from v_row.expected_agency_registry_version
       and f.agency_registry_version is distinct from p_version
       and f.source_agency_code is not distinct from v_row.source_agency_code
       and f.agency_name is not distinct from v_row.agency_name
       and f.manager_name is not distinct from v_row.manager_name
       and f.agency_key is not distinct from v_row.expected_agency_key
       and f.agency_current_name is not distinct from v_row.expected_agency_current_name
       and f.manager_key is not distinct from v_row.expected_manager_key;
    get diagnostics v_count = row_count;
    v_applied := v_applied + v_count;
    v_skipped := v_skipped + 1 - v_count;
  end loop;
  return jsonb_build_object('applied', v_applied, 'skipped', v_skipped);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_community_delete_contributions(p_user uuid, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_policy private.community_policies%rowtype := private.community_current_policy(true);
    v_id jsonb := private.community_identity_state(p_user, p_session);
    v_deletion uuid := gen_random_uuid();
    v_count integer;
    v_conns integer;
    v_fence_at timestamptz;
begin
    if not ((v_id->>'user_ok')::boolean and (v_id->>'kakao')::boolean and (v_id->>'session')::boolean) then
        return jsonb_build_object('error', 'kakao_required');
    end if;
    perform private.community_lock_contributor(p_user, false);
    perform 1 from private.community_consent_grants where user_id = p_user for update;
    perform 1 from private.community_connections where user_id = p_user for update;
    update private.community_connections set status = 'revoked', revoked_at = now(), revoke_reason = 'contributions_deleted'
     where user_id = p_user and status = 'active';
    get diagnostics v_conns = row_count;
    -- clock_timestamp() AFTER the locks (now() is the transaction start and can be older than a concurrent deletion);
    -- the stored fence never moves backwards (N-06).
    v_fence_at := clock_timestamp();
    insert into private.community_deletion_fences(contributor_id, deletion_id, fenced_at) values (p_user, v_deletion, v_fence_at)
    on conflict (contributor_id) do update
        set deletion_id = excluded.deletion_id,
            fenced_at = greatest(private.community_deletion_fences.fenced_at, excluded.fenced_at)
    returning fenced_at into v_fence_at;
    insert into private.community_fact_tombstones(contributor_id, source_report_key, deletion_id)
    select distinct contributor_id, source_report_key, v_deletion from private.community_report_facts
     where contributor_id = p_user
    on conflict do nothing;
    delete from private.community_report_facts where contributor_id = p_user;
    get diagnostics v_count = row_count;
    perform private.community_bump_projection();  -- also when there were no facts (fence/revocation changed state)
    return jsonb_build_object('deletion_id', v_deletion, 'deleted_facts', v_count, 'revoked_connections', v_conns,
        'deleted_at', v_fence_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_community_ingest(p_user uuid, p_session uuid, p_request_id text, p_envelope jsonb, p_events jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_policy private.community_policies%rowtype;
    v_profile private.contributor_profiles%rowtype;
    v_grant private.community_consent_grants%rowtype;
    v_conn private.community_connections%rowtype;
    v_fact private.community_report_facts%rowtype;
    v_lock_key text;
    v_id jsonb;
    v_ready boolean;
    v_generated timestamptz;
    v_changed boolean := false;
    v_results jsonb := '[]'::jsonb;
    v_result text;
    v_receipt uuid;
    v_existing record;
    v_max_rev bigint := 0;
    v_version text;
    e jsonb;
    d jsonb;
    v_event_id uuid;
    v_epoch bigint;
    v_rev bigint;
    v_key text;
    v_keep_grant boolean;
    v_target_grant uuid;
    v_visible boolean;
    v_was_visible boolean;
    v_fence timestamptz;
    v_projection text;
begin
    if jsonb_typeof(p_events) <> 'array' or jsonb_array_length(p_events) not between 1 and 20 then
        return jsonb_build_object('error', 'invalid_request');
    end if;
    -- One event per report per request (S-11-B): per-event ACKs then equal the committed state.
    if (select count(distinct x->>'source_report_key') from jsonb_array_elements(p_events) x) <> jsonb_array_length(p_events) then
        return jsonb_build_object('error', 'invalid_request');
    end if;
    v_policy := private.community_current_policy(true);
    select * into v_profile from private.contributor_profiles where user_id = p_user for share;
    if v_profile.user_id is null then return jsonb_build_object('error', 'consent_missing'); end if;
    if v_profile.status <> 'active' then return jsonb_build_object('error', 'contributor_suspended'); end if;
    v_id := private.community_identity_state(p_user, p_session);
    if not (v_id->>'user_ok')::boolean or not (v_id->>'kakao')::boolean then
        return jsonb_build_object('error', 'kakao_required');
    end if;
    if not (v_id->>'session')::boolean then return jsonb_build_object('error', 'session_revoked'); end if;
    select * into v_grant from private.community_consent_grants
     where grant_id = (p_envelope->>'consent_grant_id')::uuid and user_id = p_user for share;
    if v_grant.grant_id is null then return jsonb_build_object('error', 'consent_grant_unknown'); end if;
    if v_grant.revoked_at is not null then return jsonb_build_object('error', 'consent_revoked'); end if;
    if not private.community_grant_is_current(v_grant, v_policy) then return jsonb_build_object('error', 'consent_outdated'); end if;
    -- FOR UPDATE (not SHARE): this transaction later raises last_accepted_revision, and a shared lock held by a
    -- parallel ingest of the same connection would deadlock with it (S-09-R). Same-connection ingests serialize.
    select * into v_conn from private.community_connections
     where connection_id = (p_envelope->>'connection_id')::uuid and user_id = p_user for update;
    if v_conn.connection_id is null then return jsonb_build_object('error', 'connection_unknown'); end if;
    if v_conn.status = 'superseded' then return jsonb_build_object('error', 'writer_superseded'); end if;
    if v_conn.status <> 'active' then return jsonb_build_object('error', 'connection_' || v_conn.status); end if;
    if v_conn.bound_session_id <> p_session then return jsonb_build_object('error', 'connection_session_mismatch'); end if;
    if v_conn.source_app <> p_envelope->>'source_app' or v_conn.source_mode <> p_envelope->>'source_mode' then
        return jsonb_build_object('error', 'connection_mode_mismatch');
    end if;
    select fenced_at into v_fence from private.community_deletion_fences where contributor_id = p_user;
    select ready, generated_at into v_ready, v_generated from private.analytics_state where singleton;

    -- A batch can contain many reports. Acquire every report lock in a stable order before any fact row lock.
    for v_lock_key in select distinct x->>'source_report_key' from jsonb_array_elements(p_events) x
                      order by 1 loop
        perform pg_advisory_xact_lock(hashtextextended(v_lock_key, 913784));
    end loop;

    for e in select * from jsonb_array_elements(p_events) loop
        v_event_id := (e->>'event_id')::uuid;
        v_epoch := (e->>'writer_epoch')::bigint;
        v_rev := (e->>'source_revision')::bigint;
        v_key := e->>'source_report_key';
        d := e->'derived';
        if v_epoch <> v_conn.writer_epoch then
            v_results := v_results || jsonb_build_object('event_id', v_event_id, 'status', 'rejected', 'durable', false,
                'receipt_id', null, 'projection_status', 'not_applicable',
                'error', jsonb_build_object('code', 'writer_epoch_mismatch', 'retryable', false));
            continue;
        end if;
        if exists (select 1 from private.community_fact_tombstones t
                    where t.contributor_id = p_user and t.source_report_key = v_key)
           or (v_fence is not null and (e->>'captured_at')::timestamptz <= v_fence) then
            v_results := v_results || jsonb_build_object('event_id', v_event_id, 'status', 'rejected', 'durable', false,
                'receipt_id', null, 'projection_status', 'not_applicable',
                'error', jsonb_build_object('code', 'deleted', 'retryable', false));
            continue;
        end if;
        insert into private.community_ingest_events(contributor_id, event_id, request_id, connection_id, consent_grant_id,
            dataset_key, writer_epoch, source_system, source_report_key, source_report_id, source_revision, event_type,
            trigger, payload, payload_sha256, captured_at, quarantine_reason, report_number)
        values (p_user, v_event_id, p_request_id, v_conn.connection_id, v_grant.grant_id, v_conn.dataset_key, v_epoch,
            'safetyreport', v_key, e->>'source_report_id', v_rev, e->>'event_type', p_envelope->>'trigger',
            e->'payload', e->>'payload_sha256', (e->>'captured_at')::timestamptz, e->>'quarantine_reason', e->>'report_number')
        on conflict (contributor_id, event_id) do nothing
        returning receipt_id into v_receipt;
        if v_receipt is null then
            -- Immutable event fields (contract): event_type, source_report_id/key, source_revision, writer_epoch,
            -- captured_at, payload_sha256 and the connection's dataset. Grant/connection/trigger/request are transport
            -- context and may legitimately differ on a retry after rebind or policy re-consent.
            select receipt_id, payload_sha256, result, rejection_reason, dataset_key, source_report_key, source_report_id, source_revision,
                   writer_epoch, event_type, captured_at, report_number
              into v_existing from private.community_ingest_events where contributor_id = p_user and event_id = v_event_id;
            if v_existing.payload_sha256 = e->>'payload_sha256' and v_existing.dataset_key = v_conn.dataset_key
               and v_existing.source_report_key = v_key and v_existing.source_report_id = e->>'source_report_id'
               and v_existing.source_revision = v_rev and v_existing.writer_epoch = v_epoch
               and v_existing.event_type = e->>'event_type' and v_existing.captured_at = (e->>'captured_at')::timestamptz
               and v_existing.report_number is not distinct from e->>'report_number' then
                if v_existing.result = 'rejected' then
                    v_results := v_results || jsonb_build_object('event_id', v_event_id, 'status', 'rejected', 'durable', false,
                        'receipt_id', null, 'projection_status', 'not_applicable',
                        'error', jsonb_build_object('code', v_existing.rejection_reason, 'retryable', false));
                else
                    v_results := v_results || jsonb_build_object('event_id', v_event_id, 'status', 'duplicate', 'durable', true,
                        'receipt_id', v_existing.receipt_id, 'original_status', v_existing.result, 'projection_status', 'not_applicable');
                end if;
            else
                v_results := v_results || jsonb_build_object('event_id', v_event_id, 'status', 'conflict', 'durable', false,
                    'receipt_id', null, 'projection_status', 'not_applicable',
                    'error', jsonb_build_object('code', 'event_id_conflict', 'retryable', false));
            end if;
            continue;
        end if;
        -- 2026-09-28: only final-answer observations are stored. A non-eligible payload or a legacy
        -- status_correction event is rejected per event (durable=false) so the rest of the batch still
        -- processes. The central fact keeps its last answered state.
        if (e->'payload'->>'status') not in ('accepted','partial','rejected','completed_unknown')
           or e->>'event_type' = 'status_correction' then
            update private.community_ingest_events set result = 'rejected', rejection_reason = 'non_final_not_accepted'
             where receipt_id = v_receipt;
            v_results := v_results || jsonb_build_object('event_id', v_event_id, 'status', 'rejected',
                'durable', false, 'receipt_id', null, 'projection_status', 'not_applicable',
                'error', jsonb_build_object('code', 'non_final_not_accepted', 'retryable', false));
            continue;
        end if;
        if e->>'quarantine_reason' is not null then
            update private.community_ingest_events set result = 'quarantined' where receipt_id = v_receipt;
            v_results := v_results || jsonb_build_object('event_id', v_event_id, 'status', 'quarantined', 'durable', true,
                'receipt_id', v_receipt, 'projection_status', 'not_applicable');
            continue;
        end if;
        -- Sol 2026-09-28: last_accepted_revision advances only for events that reach fact processing.
        -- Rejected (non-final etc.) or quarantined events must not inflate the app's next-revision lower bound.
        v_max_rev := greatest(v_max_rev, v_rev);
        select * into v_fact from private.community_report_facts
         where contributor_id = p_user and dataset_key = v_conn.dataset_key and source_report_key = v_key for update;
        v_was_visible := v_fact.contributor_id is not null and private.community_fact_publicly_listed(v_fact);
        -- 2026-09-28 account rule: another account's fact for the same identity is left alone; this
        -- event creates (or updates) only the uploader's own contribution row. The public projection
        -- elects one representative per identity (see internal_analytics_v2_facts below).
        if v_fact.contributor_id is null then
            insert into private.community_report_facts(contributor_id, dataset_key, source_report_key, source_report_id,
                latest_receipt_id, consent_grant_id, writer_epoch, source_revision, payload_sha256, report_number, public_state,
                report_date, completed_date, category, status, disposition, amount_kind, amount_confirmed_won, penalty_points,
                vehicle_raw, lat, lng, lat_text, lng_text, coord_source, address, region_code, point_key, agency_key,
                agency_name, agency_current_name, manager_key, manager_name, violation_law, source_agency_code, rating,
                answer_accepted_at)
            values (p_user, v_conn.dataset_key, v_key, e->>'source_report_id', v_receipt, v_grant.grant_id, v_epoch, v_rev,
                e->>'payload_sha256', e->>'report_number', d->>'public_state', (d->>'report_date')::date, (d->>'completed_date')::date,
                d->>'category', d->>'status', d->>'disposition', d->>'amount_kind', (d->>'amount_confirmed_won')::bigint,
                (d->>'penalty_points')::integer, d->>'vehicle_raw', (d->>'lat')::double precision,
                (d->>'lng')::double precision, d->>'lat_text', d->>'lng_text', d->>'coord_source', d->>'address',
                d->>'region_code', d->>'point_key', d->>'agency_key', d->>'agency_name', d->>'agency_current_name',
                d->>'manager_key', d->>'manager_name',
                d->>'violation_law', d->>'source_agency_code', (d->>'rating')::integer,
                clock_timestamp());
            v_result := 'accepted';
        elsif (v_epoch, v_rev) > (v_fact.writer_epoch, v_fact.source_revision) then
            -- A fact accepted under a lineage the USER revoked stays under that (hidden) grant unless this event is an
            -- explicit reshare; policy-version supersession keeps the lineage active, so it re-attributes normally.
            v_keep_grant := v_fact.consent_grant_id <> v_grant.grant_id and e->>'event_type' <> 'reshare'
                            and not private.community_lineage_active(v_fact.consent_grant_id);
            v_target_grant := case when v_keep_grant then v_fact.consent_grant_id else v_grant.grant_id end;
            if v_fact.payload_sha256 = e->>'payload_sha256' and v_fact.consent_grant_id = v_target_grant then
                update private.community_report_facts set writer_epoch = v_epoch, source_revision = v_rev,
                    latest_receipt_id = v_receipt, report_number = coalesce(e->>'report_number', v_fact.report_number), updated_at = now()
                 where contributor_id = p_user and dataset_key = v_conn.dataset_key and source_report_key = v_key;
                v_result := 'no_change';
            else
                update private.community_report_facts set latest_receipt_id = v_receipt, consent_grant_id = v_target_grant,
                    writer_epoch = v_epoch, source_revision = v_rev, payload_sha256 = e->>'payload_sha256',
                    report_number = coalesce(e->>'report_number', v_fact.report_number),
                    public_state = d->>'public_state', report_date = (d->>'report_date')::date,
                    completed_date = (d->>'completed_date')::date, category = d->>'category', status = d->>'status',
                    disposition = d->>'disposition', amount_kind = d->>'amount_kind',
                    amount_confirmed_won = (d->>'amount_confirmed_won')::bigint, penalty_points = (d->>'penalty_points')::integer,
                    vehicle_raw = d->>'vehicle_raw', lat = (d->>'lat')::double precision, lng = (d->>'lng')::double precision,
                    lat_text = d->>'lat_text', lng_text = d->>'lng_text', coord_source = d->>'coord_source',
                    address = d->>'address', region_code = d->>'region_code', point_key = d->>'point_key',
                    -- REVIEW4 중간: 키 없는 payload(v1/v2)의 같은 기관명 갱신은
                    -- 저장된 기관 키·현행명도 보존한다. derived(d)는 코드가 없어
                    -- 기관명 해시(a1:)라서 그대로 덮으면 승계 기관의 inst: 통계가
                    -- a1:로 갈라진다. 키가 있거나(명시 null 포함) 기관명이 다르면
                    -- d 값을 쓴다(개명 답변에 옛 키 부착 금지).
                    agency_key = case when (e->'payload') ? 'source_agency_code'
                                              then d->>'agency_key'
                                              when d->>'agency_name' is not distinct from v_fact.agency_name
                                              then v_fact.agency_key
                                              else d->>'agency_key' end,
                    agency_name = d->>'agency_name',
                    agency_current_name = case when (e->'payload') ? 'source_agency_code'
                                              then d->>'agency_current_name'
                                              when d->>'agency_name' is not distinct from v_fact.agency_name
                                              then v_fact.agency_current_name
                                              else d->>'agency_current_name' end,
                    manager_key = case when (e->'payload') ? 'source_agency_code'
                                              then d->>'manager_key'
                                              when d->>'agency_name' is not distinct from v_fact.agency_name
                                              then case when d->>'manager_name' is not distinct from v_fact.manager_name
                                                        then v_fact.manager_key
                                                        when d->>'manager_name' is null
                                                        then null
                                                        else 'm1:' || substring(encode(extensions.digest(
                                                            coalesce(v_fact.agency_key, 'agency-unknown')
                                                            || '|' || normalize((d->>'manager_name'), NFC), 'sha256'), 'hex'), 1, 24) end
                                              else d->>'manager_key' end,
                    manager_name = d->>'manager_name', violation_law = d->>'violation_law',
                    rating = case when (e->'payload') ? 'rating' then (d->>'rating')::integer else v_fact.rating end,
                    -- REVIEW3 R3: v1/v2 payload 에는 source_agency_code 키가 없다.
                    -- 키가 있을 때만(명시적 NULL 포함) 쓰고, 키가 없을 때는 기관명이
                    -- 같으면 보존(같은 기관의 새 답변), 다르면 NULL(새 기관 답변에
                    -- 옛 코드를 붙이지 않는다).
                    source_agency_code = case when (e->'payload') ? 'source_agency_code'
                                              then d->>'source_agency_code'
                                              when d->>'agency_name' is not distinct from v_fact.agency_name
                                              then v_fact.source_agency_code
                                              else null end,
                    -- REVIEW3 R1: 대표 선출용 답변 수신 시각. 내용이 실제로 바뀔
                    -- 때만 갱신한다(grant 만 바뀌는 reshare·no_change 는 유지).
                    answer_accepted_at = case when v_fact.payload_sha256 is not distinct from e->>'payload_sha256'
                                              then v_fact.answer_accepted_at else clock_timestamp() end,
                    updated_at = now()
                 where contributor_id = p_user and dataset_key = v_conn.dataset_key and source_report_key = v_key;
                v_result := 'accepted';
            end if;
        else
            v_result := 'stale_ignored';
        end if;
        update private.community_ingest_events set result = v_result where receipt_id = v_receipt;
        if v_result = 'accepted' then v_changed := true; end if;
        select private.community_fact_publicly_listed(f) into v_visible from private.community_report_facts f
         where f.contributor_id = p_user and f.dataset_key = v_conn.dataset_key and f.source_report_key = v_key;
        -- published: after commit the anonymous API lists the fact; removed: it was listed and no longer is;
        -- held: listable but projection not live (ready=false / generated_at null) or its consent lineage is revoked;
        -- not_public: stored but never listed (not completed, or no report/completion date).
        v_projection := case
            when v_result <> 'accepted' then 'not_applicable'
            when coalesce(v_visible, false) and coalesce(v_ready, false) and v_generated is not null then 'published'
            when coalesce(v_was_visible, false) and not coalesce(v_visible, false) and coalesce(v_ready, false) then 'removed'
            when coalesce(v_visible, false) then 'held'
            when (select f.public_state = 'completed' and (f.report_date is not null or f.completed_date is not null)
                    from private.community_report_facts f
                   where f.contributor_id = p_user and f.dataset_key = v_conn.dataset_key and f.source_report_key = v_key)
                 then 'held'
            else 'not_public' end;
        v_results := v_results || jsonb_build_object('event_id', v_event_id, 'status', v_result, 'durable', true,
            'receipt_id', v_receipt, 'projection_status', v_projection);
    end loop;

    if v_max_rev > v_conn.last_accepted_revision then
        update private.community_connections set last_accepted_revision = v_max_rev where connection_id = v_conn.connection_id;
    end if;
    select dataset_version into v_version from private.analytics_state where singleton;
    return jsonb_build_object('results', v_results, 'dataset_version', v_version);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_community_ingest_rate_limit(p_bucket text, p_limit integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_count integer;
begin
    if p_bucket is null or p_bucket !~ '^[0-9a-f]{64}$' or p_limit not between 1 and 100000 then raise exception 'INVALID_BUCKET'; end if;
    insert into private.rate_limits(bucket, window_start, request_count)
    values (p_bucket, date_trunc('minute', now()), 1)
    on conflict (bucket, window_start) do update set request_count = private.rate_limits.request_count + 1
    returning request_count into v_count;
    return v_count <= p_limit;
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_community_manifest(p_user uuid, p_session uuid, p_connection uuid, p_after text, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_id jsonb := private.community_identity_state(p_user, p_session);
    v_conn private.community_connections%rowtype;
    v_keys jsonb;
    v_total integer;
    v_limit integer := least(greatest(coalesce(p_limit, 5000), 1), 5000);
    v_token text;
begin
    if not ((v_id->>'user_ok')::boolean and (v_id->>'kakao')::boolean) then return jsonb_build_object('error', 'kakao_required'); end if;
    if not (v_id->>'session')::boolean then return jsonb_build_object('error', 'session_revoked'); end if;
    if p_after is not null and p_after !~ '^[0-9a-f]{64}$' then return jsonb_build_object('error', 'invalid_request'); end if;
    select * into v_conn from private.community_connections where connection_id = p_connection and user_id = p_user;
    if v_conn.connection_id is null then return jsonb_build_object('error', 'connection_unknown'); end if;
    if v_conn.status <> 'active' then return jsonb_build_object('error', 'connection_' || v_conn.status); end if;
    if v_conn.bound_session_id <> p_session then return jsonb_build_object('error', 'connection_session_mismatch'); end if;
    select count(*) into v_total from private.community_report_facts f
     where f.contributor_id = p_user and f.dataset_key = v_conn.dataset_key and f.public_state = 'completed';
    -- manifest_token = generation bumped with every accepted fact change / deletion of this dataset (S-04-T).
    select coalesce((select generation::text from private.community_manifest_generations g
                      where g.contributor_id = p_user and g.dataset_key = v_conn.dataset_key), '0')
      into v_token;
    select coalesce(jsonb_agg(k order by k), '[]'::jsonb) into v_keys from (
        select f.source_report_key as k from private.community_report_facts f
         where f.contributor_id = p_user and f.dataset_key = v_conn.dataset_key and f.public_state = 'completed'
           and (p_after is null or f.source_report_key > p_after)
         order by f.source_report_key limit v_limit) page;
    return jsonb_build_object('dataset_key', v_conn.dataset_key, 'writer_epoch', v_conn.writer_epoch, 'total', v_total,
        'manifest_token', v_token,
        'key_prefixes', (select coalesce(jsonb_agg(left(x #>> '{}', 24)), '[]'::jsonb) from jsonb_array_elements(v_keys) x),
        'next_after', case when jsonb_array_length(v_keys) = v_limit then v_keys->>(v_limit - 1) else null end);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_my_analytics_cohort_source(p_user uuid, p_session uuid, p_date_basis text, p_start date, p_end date, p_with_previous boolean, p_category text, p_region_code text, p_agency_key text, p_manager_key text, p_bbox double precision[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_id jsonb;
    v_ok boolean;
    v_profile private.contributor_profiles%rowtype;
    v_contributor text;
    v_has boolean := false;
begin
    if p_user is null or p_session is null then raise exception 'INVALID_QUERY'; end if;
    v_id := private.community_identity_state(p_user, p_session);
    v_ok := (v_id->>'user_ok')::boolean and (v_id->>'kakao')::boolean and (v_id->>'session')::boolean;
    select * into v_profile from private.contributor_profiles where user_id = p_user;
    v_contributor := case
        when v_profile.user_id is null then 'none'
        when v_profile.status <> 'active' then 'suspended'
        when exists (select 1 from private.community_consent_grants g where g.user_id = p_user and g.revoked_at is null) then 'active'
        when exists (select 1 from private.community_consent_grants g where g.user_id = p_user) then 'revoked'
        else 'none' end;
    if v_ok then
        select exists (select 1 from private.community_report_facts f
                        where f.contributor_id = p_user and private.community_fact_publicly_listed(f)) into v_has;
    end if;
    return jsonb_build_object(
        'state', public.internal_analytics_cohort_state(),
        'viewer', jsonb_build_object(
            'user_ok', (v_id->>'user_ok')::boolean, 'kakao', (v_id->>'kakao')::boolean,
            'session', (v_id->>'session')::boolean, 'contributor', v_contributor, 'has_public_facts', v_has),
        -- the same public fact source as the anonymous API (same population and date rule); no rows on a failed identity
        'facts', case when v_ok then public.internal_analytics_cohort_facts(
            p_date_basis, p_start, p_end, p_with_previous, p_category, p_region_code, p_agency_key, p_manager_key, p_bbox)
            else '[]'::jsonb end);
end;
$function$

