CREATE OR REPLACE FUNCTION public.internal_my_reports_numbers(p_user uuid, p_session uuid, p_kind text, p_query text, p_offset integer, p_limit integer, p_max_total integer, p_expected_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_gate jsonb;
    v_query text;
    v_own private.my_reports_row[];
    v_sel private.my_reports_row[];
    v_version text;
    v_unique integer;
begin
    if p_user is null or p_session is null or p_offset is null or p_offset < 0 or p_limit is null
       or p_limit not between 1 and 500 or p_max_total is null or p_max_total not between 1 and 100000 then
        raise exception 'INVALID_QUERY';
    end if;
    v_query := private.my_reports_check_query(p_kind, p_query);
    v_gate := private.my_reports_gate(p_user, p_session);
    if v_gate->>'error' is not null then return jsonb_build_object('error', v_gate->>'error'); end if;

    select array_agg(o) into v_own from private.my_reports_own(p_user) o;
    v_version := private.my_reports_version(v_own, v_gate->>'contributor');
    if p_expected_version is not null and p_expected_version <> v_version then
        return jsonb_build_object('error', 'DATASET_CHANGED');
    end if;
    select array_agg(u) into v_sel from unnest(coalesce(v_own, '{}'::private.my_reports_row[])) u
     where private.my_reports_matches(u, p_kind, v_query);
    select count(distinct u.report_number) into v_unique from unnest(coalesce(v_sel, '{}'::private.my_reports_row[])) u;
    if v_unique > p_max_total then return jsonb_build_object('error', 'NUMBERS_LIMIT_EXCEEDED'); end if;

    return jsonb_build_object(
        'contributor', v_gate->>'contributor',
        'data_version', v_version,
        'query_normalized', v_query,
        'matched_reports', coalesce(cardinality(v_sel), 0),
        'without_number', (select count(*) from unnest(coalesce(v_sel, '{}'::private.my_reports_row[])) u where u.report_number is null),
        'unique_numbers', v_unique,
        'items', coalesce((select jsonb_agg(n order by n collate "C" desc)
                             from (select distinct u.report_number collate "C" as n
                                     from unnest(coalesce(v_sel, '{}'::private.my_reports_row[])) u
                                    where u.report_number is not null
                                    order by n desc
                                    offset p_offset limit p_limit) x), '[]'::jsonb));
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_my_reports_search(p_user uuid, p_session uuid, p_kind text, p_query text, p_with_summary boolean, p_reports_offset integer, p_reports_limit integer, p_managers_offset integer, p_managers_limit integer, p_expected_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_gate jsonb;
    v_query text;
    v_own private.my_reports_row[];
    v_sel private.my_reports_row[];
    v_version text;
    v_total integer;
begin
    if p_user is null or p_session is null or p_with_summary is null
       or (p_reports_offset is not null and (p_reports_offset < 0 or p_reports_limit is null or p_reports_limit not between 1 and 50))
       or (p_managers_offset is not null and (p_managers_offset < 0 or p_managers_limit is null or p_managers_limit not between 1 and 50)) then
        raise exception 'INVALID_QUERY';
    end if;
    v_query := private.my_reports_check_query(p_kind, p_query);
    v_gate := private.my_reports_gate(p_user, p_session);
    if v_gate->>'error' is not null then return jsonb_build_object('error', v_gate->>'error'); end if;

    select array_agg(o) into v_own from private.my_reports_own(p_user) o;
    v_version := private.my_reports_version(v_own, v_gate->>'contributor');
    if p_expected_version is not null and p_expected_version <> v_version then
        return jsonb_build_object('error', 'DATASET_CHANGED');
    end if;
    select array_agg(u) into v_sel from unnest(coalesce(v_own, '{}'::private.my_reports_row[])) u
     where private.my_reports_matches(u, p_kind, v_query);
    v_total := coalesce(cardinality(v_sel), 0);

    return jsonb_build_object(
        'contributor', v_gate->>'contributor',
        'data_version', v_version,
        'query_normalized', v_query,
        'summary', case when p_with_summary then private.my_reports_stats(v_sel) end,
        'reports', case when p_reports_offset is not null then jsonb_build_object(
            'items', private.my_reports_page(v_sel, p_reports_offset, p_reports_limit), 'total', v_total) end,
        'managers', case when p_managers_offset is not null then
            private.my_reports_managers(v_sel, p_managers_offset, p_managers_limit) end);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_my_reports_summary(p_user uuid, p_session uuid, p_recent_start date, p_recent_end date, p_with_summary boolean, p_offset integer, p_limit integer, p_expected_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_gate jsonb;
    v_own private.my_reports_row[];
    v_recent private.my_reports_row[];
    v_version text;
begin
    if p_user is null or p_session is null or p_with_summary is null or p_recent_start is null or p_recent_end is null
       or p_recent_end - p_recent_start <> 2 or p_offset is null or p_offset < 0 or p_limit is null
       or p_limit not between 1 and 50 then
        raise exception 'INVALID_QUERY';
    end if;
    v_gate := private.my_reports_gate(p_user, p_session);
    if v_gate->>'error' is not null then return jsonb_build_object('error', v_gate->>'error'); end if;

    select array_agg(o) into v_own from private.my_reports_own(p_user) o;
    v_version := private.my_reports_version(v_own, v_gate->>'contributor');
    if p_expected_version is not null and p_expected_version <> v_version then
        return jsonb_build_object('error', 'DATASET_CHANGED');
    end if;
    -- by the official answer date only; a report without one is never "recent"
    select array_agg(u) into v_recent from unnest(coalesce(v_own, '{}'::private.my_reports_row[])) u
     where u.completed_date between p_recent_start and p_recent_end;

    return jsonb_build_object(
        'contributor', v_gate->>'contributor',
        'data_version', v_version,
        'summary', case when p_with_summary then private.my_reports_stats(v_own) end,
        'recent_summary', case when p_with_summary then private.my_reports_stats(v_recent) end,
        'recent', jsonb_build_object('items', private.my_reports_page(v_recent, p_offset, p_limit),
                                     'total', coalesce(cardinality(v_recent), 0)));
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_safeauth_browser_status(p_id uuid, p_browser_secret_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_row private.community_auth_requests;
    v_status text;
begin
    select * into v_row from private.community_auth_requests where id = p_id for update;
    if not found or v_row.browser_secret_hash is distinct from p_browser_secret_hash then
        return jsonb_build_object('error', 'not_found');
    end if;
    v_status := private.safeauth_expire_if_needed(v_row);
    if v_status = 'code_ready' and v_row.code_expires_at <= now() then
        update private.community_auth_requests
           set status = 'failed', encrypted_auth_code = null, failed_at = now(), failed_reason_code = 'code_expired'
         where id = p_id;
        v_status := 'failed';
    end if;
    return jsonb_build_object('phase', v_status, 'expires_at', v_row.expires_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_safeauth_cancel(p_id uuid, p_actor text, p_secret_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_row private.community_auth_requests;
    v_status text;
    v_expected text;
begin
    if p_actor not in ('device', 'browser') then
        raise exception 'SAFEAUTH_INVALID_ACTOR';
    end if;
    select * into v_row from private.community_auth_requests where id = p_id for update;
    if not found then
        return jsonb_build_object('error', 'not_found');
    end if;
    v_expected := case when p_actor = 'device' then v_row.device_secret_hash else v_row.browser_secret_hash end;
    if v_expected is null or v_expected <> p_secret_hash then
        return jsonb_build_object('error', 'not_found');
    end if;
    v_status := private.safeauth_expire_if_needed(v_row);
    if v_status = 'device_confirmed' then
        return jsonb_build_object('error', 'already_completed');
    end if;
    if v_status in ('cancelled', 'expired', 'failed') then
        return jsonb_build_object('phase', v_status);
    end if;
    update private.community_auth_requests
       set status = 'cancelled', cancelled_at = now(), cancelled_by = p_actor, encrypted_auth_code = null
     where id = p_id;
    return jsonb_build_object('phase', 'cancelled');
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_safeauth_claim(p_id uuid, p_ticket_hash text, p_browser_secret_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_row private.community_auth_requests;
    v_status text;
begin
    select * into v_row from private.community_auth_requests where id = p_id for update;
    if not found or v_row.bootstrap_ticket_hash <> p_ticket_hash then
        return jsonb_build_object('error', 'not_found');
    end if;
    v_status := private.safeauth_expire_if_needed(v_row);
    if v_status in ('expired', 'cancelled', 'failed') then
        return jsonb_build_object('error', v_status);
    end if;

    if v_status = 'created' then
        update private.community_auth_requests
           set status = 'claimed', browser_secret_hash = p_browser_secret_hash, claimed_at = now()
         where id = p_id;
        v_status := 'claimed';
    elsif v_row.browser_secret_hash is distinct from p_browser_secret_hash then
        return jsonb_build_object('error', 'already_claimed');
    end if;

    return jsonb_build_object(
        'phase', v_status,
        'client_kind', v_row.client_kind,
        'device_label', v_row.device_label,
        'display_code', v_row.display_code,
        'expires_at', v_row.expires_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_safeauth_cleanup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_wiped integer;
    v_deleted integer;
begin
    -- An undelivered code that outlived its own TTL can no longer be exchanged: the request has failed
    -- (same transition as poll and browser-status), not merely lost its ciphertext.
    update private.community_auth_requests
       set status = 'failed', failed_at = now(), failed_reason_code = 'code_expired'
     where status = 'code_ready'
       and code_expires_at <= now()
       and expires_at > now();

    update private.community_auth_requests
       set encrypted_auth_code = null
     where encrypted_auth_code is not null
       and (code_expires_at <= now() or expires_at <= now());
    get diagnostics v_wiped = row_count;

    update private.community_auth_requests
       set status = 'expired'
     where status in ('created', 'claimed', 'oauth_started', 'code_ready', 'code_delivered')
       and expires_at <= now();

    delete from private.community_auth_requests
     where expires_at < now() - interval '1 day';
    get diagnostics v_deleted = row_count;

    delete from private.community_auth_rate_limits
     where window_start < now() - interval '1 day';

    return jsonb_build_object('wiped_codes', v_wiped, 'deleted_requests', v_deleted);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_safeauth_complete(p_id uuid, p_device_secret_hash text, p_user_id uuid, p_session_id uuid, p_token_issued_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_row private.community_auth_requests;
    v_status text;
begin
    select * into v_row from private.community_auth_requests where id = p_id for update;
    if not found or v_row.device_secret_hash <> p_device_secret_hash then
        return jsonb_build_object('error', 'not_found');
    end if;
    v_status := private.safeauth_expire_if_needed(v_row);
    if v_status = 'device_confirmed' then
        if v_row.user_id = p_user_id and v_row.session_id = p_session_id then
            return jsonb_build_object('phase', 'device_confirmed');
        end if;
        return jsonb_build_object('error', 'invalid_state', 'phase', v_status);
    end if;
    if v_status in ('expired', 'cancelled', 'failed') then
        return jsonb_build_object('error', v_status);
    end if;
    if v_status <> 'code_delivered' then
        return jsonb_build_object('error', 'invalid_state', 'phase', v_status);
    end if;
    if p_token_issued_at < v_row.created_at - interval '60 seconds' then
        return jsonb_build_object('error', 'session_mismatch');
    end if;
    update private.community_auth_requests
       set status = 'device_confirmed',
           user_id = p_user_id,
           session_id = p_session_id,
           completed_at = now(),
           encrypted_auth_code = null
     where id = p_id;
    return jsonb_build_object('phase', 'device_confirmed');
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_safeauth_create(p_id uuid, p_protocol integer, p_client_kind text, p_device_label text, p_display_code text, p_code_challenge text, p_create_idem_hash text, p_device_secret_hash text, p_install_hash text, p_ticket_hash text, p_ttl_seconds integer, p_max_active_per_install integer, p_max_active_total integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_existing uuid;
    v_count integer;
    v_row private.community_auth_requests;
begin
    if p_ttl_seconds is null or p_ttl_seconds < 60 or p_ttl_seconds > 1800 then
        raise exception 'SAFEAUTH_INVALID_TTL';
    end if;

    -- One creator at a time: the capacity counts below and the insert must see the same set of active rows.
    -- Row locks cannot protect rows that do not exist yet, so two concurrent creates could both pass the limit.
    perform pg_advisory_xact_lock(hashtextextended('safeauth:create-capacity', 0));

    select id into v_existing
      from private.community_auth_requests
     where create_idem_hash = p_create_idem_hash;
    if found then
        return jsonb_build_object('existing', true, 'request_id', v_existing);
    end if;

    select count(*) into v_count
      from private.community_auth_requests
     where status in ('created', 'claimed', 'oauth_started', 'code_ready', 'code_delivered')
       and expires_at > now();
    if v_count >= p_max_active_total then
        return jsonb_build_object('error', 'capacity');
    end if;

    if p_install_hash is not null then
        select count(*) into v_count
          from private.community_auth_requests
         where install_hash = p_install_hash
           and status in ('created', 'claimed', 'oauth_started', 'code_ready', 'code_delivered')
           and expires_at > now();
        if v_count >= p_max_active_per_install then
            return jsonb_build_object('error', 'too_many_pending');
        end if;
    end if;

    insert into private.community_auth_requests (
        id, protocol_version, client_kind, device_label, display_code, code_challenge,
        create_idem_hash, device_secret_hash, install_hash, bootstrap_ticket_hash, expires_at)
    values (
        p_id, p_protocol, p_client_kind, p_device_label, p_display_code, p_code_challenge,
        p_create_idem_hash, p_device_secret_hash, p_install_hash, p_ticket_hash,
        now() + make_interval(secs => p_ttl_seconds))
    on conflict (create_idem_hash) do nothing
    returning * into v_row;

    if v_row.id is null then
        select id into v_existing
          from private.community_auth_requests
         where create_idem_hash = p_create_idem_hash;
        return jsonb_build_object('existing', true, 'request_id', v_existing);
    end if;

    return jsonb_build_object(
        'existing', false,
        'request_id', v_row.id,
        'display_code', v_row.display_code,
        'expires_at', v_row.expires_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_safeauth_poll(p_id uuid, p_device_secret_hash text, p_delivery_key_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_row private.community_auth_requests;
    v_status text;
begin
    select * into v_row from private.community_auth_requests where id = p_id for update;
    if not found or v_row.device_secret_hash <> p_device_secret_hash then
        return jsonb_build_object('error', 'not_found');
    end if;
    v_status := private.safeauth_expire_if_needed(v_row);

    if v_status in ('created', 'claimed', 'oauth_started') then
        return jsonb_build_object('status', 'pending', 'phase', v_status, 'expires_at', v_row.expires_at);
    elsif v_status = 'device_confirmed' then
        return jsonb_build_object('status', 'completed');
    elsif v_status in ('expired', 'cancelled', 'failed') then
        return jsonb_build_object('status', v_status, 'reason',
            coalesce(v_row.failed_reason_code, v_row.cancelled_by));
    end if;

    if v_row.delivery_key_hash is not null and v_row.delivery_key_hash <> p_delivery_key_hash then
        return jsonb_build_object('error', 'delivery_conflict');
    end if;
    if v_row.code_expires_at <= now() then
        update private.community_auth_requests
           set encrypted_auth_code = null,
               status = case when status = 'code_ready' then 'failed' else status end,
               failed_at = case when status = 'code_ready' then now() else failed_at end,
               failed_reason_code = case when status = 'code_ready' then 'code_expired' else failed_reason_code end
         where id = p_id;
        return jsonb_build_object('status', 'code_expired');
    end if;
    if v_row.encrypted_auth_code is null then
        return jsonb_build_object('status', 'code_expired');
    end if;

    if v_status = 'code_ready' then
        update private.community_auth_requests
           set status = 'code_delivered', delivery_key_hash = p_delivery_key_hash, delivered_at = now()
         where id = p_id;
    end if;
    return jsonb_build_object(
        'status', 'code',
        'encrypted_auth_code', v_row.encrypted_auth_code,
        'code_expires_at', v_row.code_expires_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_safeauth_prepare(p_id uuid, p_browser_secret_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_row private.community_auth_requests;
    v_status text;
begin
    select * into v_row from private.community_auth_requests where id = p_id for update;
    if not found or v_row.browser_secret_hash is distinct from p_browser_secret_hash then
        return jsonb_build_object('error', 'not_found');
    end if;
    v_status := private.safeauth_expire_if_needed(v_row);
    if v_status in ('expired', 'cancelled', 'failed') then
        return jsonb_build_object('error', v_status);
    end if;
    if v_status not in ('claimed', 'oauth_started') then
        return jsonb_build_object('error', 'invalid_state', 'phase', v_status);
    end if;
    if v_row.prepare_count >= 3 then
        return jsonb_build_object('error', 'prepare_limit');
    end if;
    update private.community_auth_requests
       set status = 'oauth_started',
           prepare_count = prepare_count + 1,
           oauth_started_at = coalesce(oauth_started_at, now())
     where id = p_id;
    return jsonb_build_object(
        'phase', 'oauth_started',
        'code_challenge', v_row.code_challenge,
        'expires_at', v_row.expires_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_safeauth_publish(p_id uuid, p_browser_secret_hash text, p_kind text, p_code_digest text, p_encrypted_code text, p_code_ttl_seconds integer, p_error_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_row private.community_auth_requests;
    v_status text;
begin
    if p_kind not in ('code', 'denied', 'error') then
        raise exception 'SAFEAUTH_INVALID_KIND';
    end if;
    select * into v_row from private.community_auth_requests where id = p_id for update;
    if not found or v_row.browser_secret_hash is distinct from p_browser_secret_hash then
        return jsonb_build_object('error', 'not_found');
    end if;
    v_status := private.safeauth_expire_if_needed(v_row);

    -- A repeated publish of the same code is idempotent in every later phase.
    if p_kind = 'code' and v_row.code_digest is not null then
        if v_row.code_digest = p_code_digest then
            return jsonb_build_object('phase', v_status);
        end if;
        return jsonb_build_object('error', 'code_conflict');
    end if;

    if v_status in ('expired', 'cancelled', 'failed') then
        return jsonb_build_object('error', v_status);
    end if;
    if v_status <> 'oauth_started' then
        return jsonb_build_object('error', 'invalid_state', 'phase', v_status);
    end if;

    if p_kind = 'code' then
        if p_code_ttl_seconds is null or p_code_ttl_seconds < 10 or p_code_ttl_seconds > 300 then
            raise exception 'SAFEAUTH_INVALID_TTL';
        end if;
        update private.community_auth_requests
           set status = 'code_ready',
               encrypted_auth_code = p_encrypted_code,
               code_digest = p_code_digest,
               code_expires_at = least(now() + make_interval(secs => p_code_ttl_seconds), v_row.expires_at),
               published_at = now()
         where id = p_id;
        return jsonb_build_object('phase', 'code_ready');
    elsif p_kind = 'denied' then
        update private.community_auth_requests
           set status = 'cancelled', cancelled_at = now(), cancelled_by = 'oauth'
         where id = p_id;
        return jsonb_build_object('phase', 'cancelled');
    else
        update private.community_auth_requests
           set status = 'failed', failed_at = now(), failed_reason_code = 'oauth_error'
         where id = p_id;
        return jsonb_build_object('phase', 'failed');
    end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_safeauth_rate_limit(p_bucket text, p_limit integer, p_window_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_window timestamptz;
    v_count integer;
begin
    if p_bucket is null or p_bucket !~ '^sa:[a-z_]{2,16}:[0-9a-f]{64}$' then
        raise exception 'SAFEAUTH_INVALID_BUCKET';
    end if;
    if p_window_seconds is null or p_window_seconds < 1 or p_window_seconds > 3600 or p_limit < 1 then
        raise exception 'SAFEAUTH_INVALID_WINDOW';
    end if;
    v_window := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
    insert into private.community_auth_rate_limits(bucket, window_start, request_count)
    values (p_bucket, v_window, 1)
    on conflict (bucket, window_start) do update
        set request_count = private.community_auth_rate_limits.request_count + 1
    returning request_count into v_count;
    return jsonb_build_object(
        'allowed', v_count <= p_limit,
        'retry_after', greatest(1, ceil(extract(epoch from (v_window + make_interval(secs => p_window_seconds) - now())))::integer));
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_safeauth_rotate_ticket(p_id uuid, p_device_secret_hash text, p_ticket_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_row private.community_auth_requests;
    v_status text;
begin
    select * into v_row from private.community_auth_requests where id = p_id for update;
    if not found or v_row.device_secret_hash <> p_device_secret_hash then
        return jsonb_build_object('error', 'not_found');
    end if;
    v_status := private.safeauth_expire_if_needed(v_row);
    if v_status <> 'created' then
        return jsonb_build_object('error', 'request_not_reusable', 'status', v_status);
    end if;
    update private.community_auth_requests
       set bootstrap_ticket_hash = p_ticket_hash
     where id = p_id;
    return jsonb_build_object(
        'request_id', v_row.id,
        'display_code', v_row.display_code,
        'expires_at', v_row.expires_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.internal_user_rankings(p_user uuid, p_session uuid, p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET work_mem TO '32MB'
 SET statement_timeout TO '20s'
AS $function$
declare
 q jsonb:=p_query; v_gate jsonb; v_scope jsonb; v_result jsonb;
 v_theme text; v_metric text; v_period text; v_basis text; v_category text; v_month text;
 v_start date; v_end date; v_today date:=(statement_timestamp() at time zone 'Asia/Seoul')::date;
 v_min bigint; v_page bigint; v_size integer; v_expected text;
begin
 if p_user is null or p_session is null or q is null or jsonb_typeof(q)<>'object' then raise exception 'INVALID_QUERY'; end if;
 if exists(select 1 from jsonb_object_keys(q) k where k not in ('theme','metric','period','start','end','month','date_basis','category','min_reports','page','page_size','expected_version')) then raise exception 'INVALID_QUERY'; end if;
 v_theme:=q->>'theme'; v_metric:=q->>'metric'; v_period:=q->>'period'; v_basis:=q->>'date_basis'; v_category:=q->>'category';
 v_min:=(q->>'min_reports')::bigint; v_page:=(q->>'page')::bigint; v_size:=(q->>'page_size')::integer; v_expected:=q->>'expected_version';
 if v_theme is null or v_metric is null or v_period is null or v_basis is null or v_category is null
   or v_min is null or v_page is null or v_size is null or v_min<1 or v_min>9007199254740991 or v_page<1 or v_page>9007199254740991 or v_size not between 1 and 50
   or v_theme not in ('reporters','fines','unlucky') or v_period not in ('all','range','month')
   or v_basis not in ('completed_date','report_date') or v_category not in ('all','traffic','parking','other')
   or not ((v_theme='reporters' and v_metric='reports_count') or (v_theme='fines' and v_metric in ('fine_count','fine_rate'))
        or (v_theme='unlucky' and v_metric in ('rejected_count','rejected_rate','partial_count','partial_rate')))
   or (v_expected is not null and v_expected !~ '^[a-f0-9]{32}$') or (v_page>1 and v_expected is null)
 then raise exception 'INVALID_QUERY'; end if;
 if v_period='range' then
   if q->>'month' is not null or q->>'start' is null or q->>'end' is null
      or q->>'start' !~ '^\d{4}-\d{2}-\d{2}$' or q->>'end' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'INVALID_QUERY'; end if;
   v_start:=(q->>'start')::date; v_end:=(q->>'end')::date;
   if v_start>v_end then raise exception 'INVALID_QUERY'; end if;
 else
   if q->>'start' is not null or q->>'end' is not null then raise exception 'INVALID_QUERY'; end if;
   if v_period='month' then
     v_month:=coalesce(q->>'month',to_char(v_today,'YYYY-MM'));
     if v_month !~ '^\d{4}-(0[1-9]|1[0-2])$' then raise exception 'INVALID_QUERY'; end if;
     v_start:=(v_month||'-01')::date; v_end:=(v_start+interval '1 month'-interval '1 day')::date;
   elsif q->>'month' is not null then raise exception 'INVALID_QUERY'; end if;
 end if;
 -- Same map eligibility; checked again inside the aggregate RPC on every page.
 v_gate:=public.internal_analytics_viewer(p_user,p_session);
 if not coalesce((v_gate->>'user_ok')::boolean,false) then return jsonb_build_object('error','session_expired'); end if;
 if not coalesce((v_gate->>'kakao')::boolean,false) then return jsonb_build_object('error','kakao_required'); end if;
 if not coalesce((v_gate->>'session')::boolean,false) then return jsonb_build_object('error','session_expired'); end if;
 if v_gate->>'contributor' is distinct from 'active' then return jsonb_build_object('error','contributor_required'); end if;
 if coalesce((v_gate->>'public_fact_count')::bigint,0)<10 then
   return jsonb_build_object('error','upload_required','details',jsonb_build_object('required',10,'current',v_gate->'public_fact_count'));
 end if;
 v_scope:=jsonb_build_object('theme',v_theme,'metric',v_metric,'period',v_period,'start',v_start,'end',v_end,'month',v_month,
   'date_basis',v_basis,'category',v_category,'min_reports',v_min,'timezone','Asia/Seoul',
   'in_progress',v_period='month' and v_month=to_char(v_today,'YYYY-MM'));
 with totals as materialized (
   -- Scan the elected representatives once. Date/category are applied AFTER election, including diagnostics.
   select r.contributor_id,
     count(*) filter(where x.in_scope) as reports,
     count(*) filter(where x.in_scope and r.status in ('accepted','partial') and r.disposition='fine') as fine,
     count(*) filter(where x.in_scope and r.status='rejected') as rejected,
     count(*) filter(where x.in_scope and r.status='partial') as partial,
     count(*) filter(where x.in_scope and r.status='completed_unknown') as completed_unknown,
     count(*) filter(where x.selected_date is null and (v_category='all' or r.category=v_category)) as missing_date,
     count(*) filter(where x.in_scope and r.disposition in ('fine','penalty','warning') and r.status not in ('accepted','partial')) as inconsistent
   from private.ranking_representatives() r
   cross join lateral (select case v_basis when 'report_date' then r.report_date else r.completed_date end as d) dt
   cross join lateral (select dt.d as selected_date, (v_category='all' or r.category=v_category) and dt.d is not null
     and (v_start is null or dt.d between v_start and v_end) as in_scope) x
   group by r.contributor_id
 ), stats as materialized (
   -- Keep original field order/types: the version hash uses this exact composite text.
   select contributor_id,reports,fine,rejected,partial,completed_unknown from totals where reports>0
 ), diagnostics as (
   select jsonb_build_object('selected_date_missing',coalesce(sum(missing_date),0),
     'completed_unknown',coalesce(sum(completed_unknown),0),
     'inconsistent_disposition',coalesce(sum(inconsistent),0)) as value from totals
 ), version as (
   -- Hash ALL participant aggregates + full scope + diagnostics. No raw identity/UUID list is exported.
   select left(encode(sha256(convert_to(v_scope::text||'#size='||v_size||'#'||d.value::text||'#'||
     coalesce((select string_agg(s::text,E'\n' order by s.contributor_id) from stats s),''),'UTF8')),'hex'),32) as value from diagnostics d
 ), measures as (
   select s.*,case v_metric when 'reports_count' then s.reports when 'fine_count' then s.fine when 'fine_rate' then s.fine
     when 'rejected_count' then s.rejected when 'rejected_rate' then s.rejected else s.partial end as numerator,
     case when right(v_metric,5)='_rate' then s.reports else 1::bigint end as sort_denominator
   from stats s where s.reports>=v_min
 ), scores as (
   -- Exact order embedding on safe integer counts (N <= 2^53-1): distinct fractions differ by
   -- at least 1/(2^53-1)^2 > 10^-32. Integer quotient at scale 10^40 cannot merge
   -- unequal fractions. Equal fractions produce equal keys. No rounded/display rate sorts.
   select m.*,div(m.numerator::numeric * 10000000000000000000000000000000000000000::numeric,m.sort_denominator::numeric) as score
   from measures m
 ), ranks as (
   select s.*,rank() over(order by s.score desc) as rank from scores s
 ), ordered as (
   select r.*,count(*) over(partition by r.rank) as tie_count,
     row_number() over(order by r.rank,r.reports desc,r.contributor_id) as ord
   from ranks r
 ), rows as (
   select o.ord,o.contributor_id,jsonb_build_object('uuid',o.contributor_id,'rank',o.rank,'tie_count',o.tie_count,
     'reports',o.reports,'fine',o.fine,'rejected',o.rejected,'partial',o.partial,'completed_unknown',o.completed_unknown,
     'numerator',o.numerator,'denominator',o.reports,
     'value',case when right(v_metric,5)='_rate' then o.numerator*100.0/nullif(o.reports,0) else o.numerator::numeric end,
     'is_me',o.contributor_id=p_user) as value from ordered o
   where o.contributor_id=p_user or (o.ord>(v_page-1)*v_size and o.ord<=v_page*v_size)
 ) select case when v_expected is not null and v_expected<>v.value then jsonb_build_object('error','DATASET_CHANGED') else
   jsonb_build_object('schema_version','user-rankings-v1','cohort_policy_version','single-date-v1','dataset_version',v.value,
    'generated_at',to_char(statement_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'scope',v_scope,
    'total_participants',(select count(*) from measures),
    'rows',coalesce((select jsonb_agg(r.value order by r.ord) from rows r where r.ord>(v_page-1)*v_size and r.ord<=v_page*v_size),'[]'::jsonb),
    'me',(select r.value from rows r where r.contributor_id=p_user), 'page',v_page,'page_size',v_size,
    'next_page',case when (select count(*) from measures)>v_page*v_size then v_page+1 else null end,'diagnostics',d.value) end
   into v_result from version v cross join diagnostics d;
 return v_result;
exception when invalid_text_representation or datetime_field_overflow or numeric_value_out_of_range then raise exception 'INVALID_QUERY';
end;
$function$
